bs(x = &quot;Median genome length (bp) per sample&quot;, y = &quot;Richness&quot;) + ylim(c(0, 150)) + theme_minimal() + custom_ggplot_theme # Display the plot 9.4.3 Statistical Modeling: Negative Binomial Regression # Recalculate median lengths (if needed) and prepare data for modeling tidy_plot_genome_counts_filt_30_macro_closed_zerosrem &lt;- tidy_plot_genome_counts_filt_30_macro_closed %&gt;% filter(count &gt; 0) median_lengths &lt;- tidy_plot_genome_counts_filt_30_macro_closed_zerosrem %&gt;% group_by(microsample) %&gt;% summarise(median_genome_length = median(length, na.rm = TRUE), .groups = &quot;drop&quot;) # Join with alpha diversity and filter out controls alpha_div_macro_filtered_30_gen_length &lt;- alpha_div_macro_filtered_30 %&gt;% left_join(median_lengths, by = join_by(microsample == microsample)) %&gt;% left_join(sample_metadata_macro, by = join_by(microsample == sample)) %&gt;% filter(treatment != &quot;TF0&quot;) # Fit negative binomial regression model (appropriate for count data) model_nb &lt;- glm.nb(richness ~ median_genome_length, data = alpha_div_macro_filtered_30_gen_length) # Fit null model (intercept only) for comparison model_null &lt;- glm.nb(richness ~ 1, data = alpha_div_macro_filtered_30_gen_length) # Calculate McFadden pseudo-R² (model fit metric) pseudo_r2 &lt;- 1 - (logLik(model_nb) / logLik(model_null)) cat(&quot;McFadden pseudo-R² =&quot;, round(pseudo_r2, 3), &quot;
